<?php if ($isLoggedIn): ?>
<?php if ($isAdmin): ?><a class="admin-link" href="/smart-toolz/admin/" title="Open SmartToolz Admin"><span class="material-symbols-rounded">shield_person</span> Admin</a><?php endif; ?>
