<a href="/creator-ai/auth/logout.php"><span class="material-symbols-rounded">logout</span> Logout</a>
<?php else: ?><a class="login-btn" href="/creator-ai/auth/google-login.php"><span class="material-symbols-rounded">login</span> Login with Google</a><?php endif; ?></div>
<?php if ($isLoggedIn): ?><div class="notification-panel" id="notificationPanel"><div class="notification-head"><strong><span class="material-symbols-rounded">notifications_active</span> Activity</strong><button id="markAllRead" type="button">Mark all read</button></div><div id="notificationList"><div class="notification-empty">Loading…</div></div></div><?php endif; ?></nav></header>
<?php if (!$isHome && !$isAccount && !$isAllTools && !$isAdminArea): ?>
<section class="tool-seo-intro"><div><span class="tool-free-badge">FREE ONLINE TOOL</span><h2>Free Online <?= htmlspecialchars($toolTitle, ENT_QUOTES, 'UTF-8') ?></h2><p><?= htmlspecialchars($siteName, ENT_QUOTES, 'UTF-8') ?> <?= htmlspecialchars($toolTitle, ENT_QUOTES, 'UTF-8') ?> helps you complete this task quickly and easily. <?= htmlspecialchars($siteTagline, ENT_QUOTES, 'UTF-8') ?></p></div><div class="how-use"><h3><span class="material-symbols-rounded">menu_book</span> How to Use</h3><ol><li>Enter, upload or select your data.</li><li>Choose your options and click the main action button.</li><li>Review the result and download or copy it.</li></ol></div></section>
<?php if ($showToolAd && $adsEnabled && $adsClient !== '' && $adsSlot !== ''): ?><div class="st-ad-wrap" aria-label="Advertisement"><div class="st-ad-label">Advertisement</div><ins class="adsbygoogle" style="display:block" data-ad-client="<?= htmlspecialchars($adsClient, ENT_QUOTES, 'UTF-8') ?>" data-ad-slot="<?= htmlspecialchars($adsSlot, ENT_QUOTES, 'UTF-8') ?>" data-ad-format="<?= htmlspecialchars($adsFormat, ENT_QUOTES, 'UTF-8') ?>" data-full-width-responsive="true"></ins><script>(adsbygoogle=window.adsbygoogle||[]).push({});</script></div><?php endif; ?>
<?php endif; ?>
