;border:1px solid #e3e7ef;border-radius:16px;box-shadow:0 18px 50px rgba(20,30,70,.18);overflow:hidden}.notification-panel.open{display:block}.notification-head{display:flex;align-items:center;justify-content:space-between;padding:14px 15px;border-bottom:1px solid #edf0f4}.notification-head strong{display:inline-flex;align-items:center;gap:6px;font-size:13px}.notification-head strong .material-symbols-rounded{color:#635bff;font-size:18px}.notification-head button{border:0;background:transparent;color:#635bff;font-size:11px;font-weight:800;cursor:pointer}.notification-item{padding:12px 15px;border-bottom:1px solid #f0f2f5;cursor:pointer}.notification-item.unread{background:#f7f6ff}.notification-item strong{display:block;font-size:12px}.notification-item p{margin:4px 0;color:#697489;font-size:11px;line-height:1.5}.notification-item small{color:#98a0ae;font-size:10px}.notification-empty{padding:25px;text-align:center;color:#8791a2;font-size:12px}.nav-user{display:flex!important;align-items:center;gap:7px!important}.nav-user img,.nav-user>span{width:30px;height:30px;border-radius:50%;object-fit:cover}.nav-user>span{display:grid;place-items:center;background:#635bff;color:#fff;font-size:12px}.menu-button{display:none;border:0;background:transparent;color:#172033;width:42px;height:42px;border-radius:10px;cursor:pointer}.menu-button .material-symbols-rounded{font-size:27px}.tool-seo-intro{width:100%;max-width:none;box-sizing:border-box;margin:24px 0 0;padding:24px 26px;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:22px;background:#fff;border:1px solid #e5e9f0;border-radius:20px;box-shadow:0 10px 35px rgba(20,30,70,.045)}.tool-free-badge{display:inline-flex;align-items:center;gap:5px;padding:6px 10px;border-radius:999px;background:#eeedff;color:#635bff;font-size:10px;font-weight:900;letter-spacing:.4px}.tool-seo-intro h2{margin:9px 0 7px;font-size:26px;line-height:1.15}.tool-seo-intro p{margin:0;color:#707b8e;font-size:13px;line-height:1.7}.how-use{padding:18px;background:#f7f8fc;border:1px solid #e8eaf1;border-radius:15px}.how-use h3{display:flex;align-items:center;gap:6px;margin:0 0 8px;font-size:16px}.how-use h3 .material-symbols-rounded{color:#635bff;font-size:20px}.how-use ol{margin:0;padding-left:20px;color:#596477;font-size:12px;line-height:1.8}.st-ad-wrap{width:min(1400px,calc(100% - 30px));min-height:108px;margin:16px auto 8px;padding:8px 0;text-align:center;overflow:hidden}.st-ad-label{margin:0 0 6px;color:#9aa2b1;font-size:9px;font-weight:700;letter-spacing:.4px;text-transform:uppercase}.st-ad-wrap .adsbygoogle{min-height:90px}@media(max-width:820px){.menu-button{display:grid;place-items:center}.nav-links{display:none;position:absolute;top:66px;left:0;right:0;padding:12px;flex-direction:column;align-items:stretch;background:#fff;border:1px solid #e7eaf1;border-top:0;border-radius:0 0 16px 16px;box-shadow:0 18px 35px rgba(20,28,50,.1)}.nav-links.open{display:flex}.nav-links>a,.notify-btn{margin:2px 0}.nav-links>a{justify-content:flex-start;padding:11px 12px}.notify-btn{width:100%;height:42px;display:flex;justify-content:flex-start;padding-left:12px}.notify-btn b{right:auto;left:29px}.nav-user{justify-content:flex-start!important;padding:9px 12px!important}.notification-panel{right:8px;top:64px}.tool-seo-intro{grid-template-columns:1fr;width:100%;margin-left:0;margin-right:0}.st-ad-wrap{width:min(100% - 24px,1400px);min-height:96px}}@media(max-width:560px){.navbar{min-height:64px;padding:0 10px}.logo{font-size:18px}.logo-icon{width:38px;height:38px}.tool-seo-intro{padding:19px}.st-ad-wrap{min-height:84px}}
