<script>(()=>{const b=document.querySelector('.menu-button'),n=document.querySelector('.nav-links');if(b&&n)b.addEventListener('click',()=>{const open=n.classList.toggle('open');b.setAttribute('aria-expanded',open?'true':'false');const i=b.querySelector('.material-symbols-rounded');if(i)i.textContent=open?'close':'menu'});const logged=<?= $isLoggedIn?'true':'false' ?>;if(!logged)return;const btn=document.getElementById('notifyBtn'),panel=document.getElementById('notificationPanel'),list=document.getElementById('notificationList'),count=document.getElementById('notifyCount');async function load(){try{const r=await fetch('/smart-toolz/api/notifications.php?action=list',{cache:'no-store'}),d=await r.json();if(!d.ok)return;if(count){count.textContent=d.unread||0;count.hidden=!(d.unread>0)}if(list)list.innerHTML=(d.notifications||[]).map(x=>`<div class="notification-item ${x.read_at?'':'unread'}"><strong>${String(x.title||'')}</strong><p>${String(x.message||'')}</p><small>${String(x.created_at||'')}</small></div>`).join('')||'<div class="notification-empty">No activity yet.</div>'}catch(e){}}if(btn&&panel){btn.onclick=()=>{panel.classList.toggle('open');load()};document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!btn.contains(e.target))panel.classList.remove('open')})}load();const mark=document.getElementById('markAllRead');if(mark)mark.onclick=async()=>{await fetch('/smart-toolz/api/notifications.php?action=read_all',{method:'POST'});load()}})();</script>